#![allow(unused_imports)]
use verus::prelude::*;

verus! {
    /// Given a non‐negative integer `n`, produce a `Vec<i8>` of length `n`
    /// where every entry is exactly `1`.
    ///
    /// Properties:
    /// 1. result.len() == n
    /// 2. ∀ k < n: result[k] == 1
    /// 3. ∀ i, j < n: result[i] == result[j]
    /// 4. ∀ k < n: result[k] > 0
    pub fn ones(n: usize) -> (result: Vec<i8>)
        ensures result.len() == n
        ensures forall|k: usize| k < n ==> result[k] == 1
        ensures forall|i, j: usize| i < n && j < n ==> result[i] == result[j]
        ensures forall|k: usize| k < n ==> result[k] > 0
    {
        let mut res: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        // Build the vector by pushing `1` exactly `n` times.
        while i < n
            invariant i <= n
            invariant res.len() == i
            invariant forall|k: usize| k < i ==> res[k] == 1
            decreases n - i
        {
            res.push(1);
            i += 1;
        }
        res
    }
}